BACKEND_H = os.path.join(BASE, "ggml-cuda8-ggml-backend.h")
BACKEND_CPP = os.path.join(BASE, "ggml-cuda8-ggml-backend.cpp")
PROBE_CPP = os.path.join(BASE, "ggml-cuda8-ggml-backend-graph-compute-add-smoke.cpp")
CMAKE = os.path.join(BASE, "CMakeLists.txt")
BACKEND_H_TEXT = '// ggml/src/ggml-cuda8/ggml-cuda8-ggml-backend.h\n//\n// G12A/G13A/G14B/G15A: minimal ggml_backend_t wrapper/probe for CUDA8.\n\n#ifndef GGML_CUDA8_GGML_BACKEND_H\n#define GGML_CUDA8_GGML_BACKEND_H\n\n#include "ggml-backend.h"\n#include "ggml-cuda8-dispatch.h"\n\n#ifdef __cplusplus\nextern "C" {\n#endif\n\nggml_backend_t ggml_cuda8_ggml_backend_init(int device);\nint ggml_cuda8_ggml_backend_is_cuda8(ggml_backend_t backend);\nggml_backend_buffer_type_t ggml_cuda8_ggml_backend_get_default_buffer_type(ggml_backend_t backend);\n\n// G13A/G13B: compute-shaped helper used by backend-owned smoke graphs.\n// This helper remains useful as the stable single-op dispatch path.\nint ggml_cuda8_ggml_backend_dispatch_op(\n    ggml_backend_t backend,\n    ggml_cuda8_context * ctx,\n    int op,\n    const ggml_tensor * src0,\n    const ggml_tensor * src1,\n    ggml_tensor * dst\n);\n\n#ifdef __cplusplus\n}\n#endif\n\n#endif // GGML_CUDA8_GGML_BACKEND_H\n'
BACKEND_CPP_TEXT = '// ggml/src/ggml-cuda8/ggml-cuda8-ggml-backend.cpp\n//\n// G12A/G13A/G14B/G15A: minimal ggml_backend_t wrapper/probe for CUDA8.\n//\n// This checkout\'s ggml_backend_i has graph callbacks but does not expose\n// get_default_buffer_type. Default buffer type remains available through the\n// local helper ggml_cuda8_ggml_backend_get_default_buffer_type().\n//\n// G15A turns graph_compute from a pure stub into a tiny real executor for a\n// synthetic ADD_F32 graph. Unsupported graph nodes still return failure.\n\n#include "ggml-cuda8-ggml-backend.h"\n#include "ggml-cuda8-ggml-buffer.h"\n#include "ggml-cuda8-dispatch.h"\n\n#include "ggml.h"\n#include "ggml-backend-impl.h"\n\n#include <cstdio>\n#include <cstdlib>\n#include <cstring>\n\nstruct ggml_cuda8_ggml_backend_context {\n    int device;\n};\n\nstatic const char * cuda8_backend_get_name(ggml_backend_t backend) {\n    (void) backend;\n    return "CUDA8";\n}\n\nstatic void cuda8_backend_free(ggml_backend_t backend) {\n    if (backend == NULL) return;\n    ggml_cuda8_ggml_backend_context * ctx = (ggml_cuda8_ggml_backend_context *) backend->context;\n    if (ctx != NULL) std::free(ctx);\n    std::free(backend);\n}\n\nstatic void cuda8_backend_synchronize(ggml_backend_t backend) {\n    (void) backend;\n    std::printf("ggml-cuda8/backend: synchronize PASS\\n");\n}\n\nstatic ggml_backend_graph_plan_t cuda8_backend_graph_plan_create(ggml_backend_t backend, const struct ggml_cgraph * cgraph) {\n    (void) backend;\n    (void) cgraph;\n    std::printf("ggml-cuda8/backend: graph_plan_create stub PASS\\n");\n    return NULL;\n}\n\nstatic void cuda8_backend_graph_plan_free(ggml_backend_t backend, ggml_backend_graph_plan_t plan) {\n    (void) backend;\n    (void) plan;\n    std::printf("ggml-cuda8/backend: graph_plan_free stub PASS\\n");\n}\n\nstatic void cuda8_backend_graph_plan_update(ggml_backend_t backend, ggml_backend_graph_plan_t plan, const struct ggml_cgraph * cgraph) {\n    (void) backend;\n    (void) plan;\n    (void) cgraph;\n    std::printf("ggml-cuda8/backend: graph_plan_update stub PASS\\n");\n}\n\nstatic enum ggml_status cuda8_backend_graph_plan_compute(ggml_backend_t backend, ggml_backend_graph_plan_t plan) {\n    (void) backend;\n    (void) plan;\n    std::printf("ggml-cuda8/backend: graph_plan_compute stub PASS\\n");\n    return GGML_STATUS_SUCCESS;\n}\n\nstatic enum ggml_status cuda8_backend_graph_compute(ggml_backend_t backend, struct ggml_cgraph * cgraph) {\n    if (!ggml_cuda8_ggml_backend_is_cuda8(backend)) {\n        std::fprintf(stderr, "ggml-cuda8/backend graph_compute: invalid backend\\n");\n        return (enum ggml_status) -1;\n    }\n\n    if (cgraph == NULL) {\n        // Preserve G14B graph API probe behavior.\n        std::printf("ggml-cuda8/backend: graph_compute NULL-graph stub PASS\\n");\n        return GGML_STATUS_SUCCESS;\n    }\n\n    ggml_cuda8_context * ctx = NULL;\n    if (ggml_cuda8_context_create(0, &ctx) != 0 || ctx == NULL) {\n        std::fprintf(stderr, "ggml-cuda8/backend graph_compute: failed to create CUDA8 context\\n");\n        return (enum ggml_status) -1;\n    }\n\n    std::printf("ggml-cuda8/backend: graph_compute starting n_nodes=%d\\n", cgraph->n_nodes);\n\n    for (int i = 0; i < cgraph->n_nodes; ++i) {\n        struct ggml_tensor * node = cgraph->nodes[i];\n        if (node == NULL) {\n            continue;\n        }\n\n        if (node->op == GGML_OP_NONE) {\n            continue;\n        }\n\n        if (node->op != GGML_OP_ADD) {\n            std::fprintf(stderr,\n                "ggml-cuda8/backend graph_compute: unsupported node %d op=%d\\n",\n                i,\n                (int) node->op);\n            ggml_cuda8_context_destroy(ctx);\n            return (enum ggml_status) -1;\n        }\n\n        if (node->type != GGML_TYPE_F32 ||\n            node->src[0] == NULL ||\n            node->src[1] == NULL ||\n            node->src[0]->type != GGML_TYPE_F32 ||\n            node->src[1]->type != GGML_TYPE_F32) {\n            std::fprintf(stderr,\n                "ggml-cuda8/backend graph_compute: ADD node %d is not F32/F32/F32\\n",\n                i);\n            ggml_cuda8_context_destroy(ctx);\n            return (enum ggml_status) -1;\n        }\n\n        std::printf("ggml-cuda8/backend: graph_compute node %d ADD_F32\\n", i);\n\n        if (ggml_cuda8_ggml_backend_dispatch_op(\n                backend,\n                ctx,\n                GGML_CUDA8_OP_ADD_F32,\n                node->src[0],\n                node->src[1],\n                node) != 0) {\n            std::fprintf(stderr,\n                "ggml-cuda8/backend graph_compute: ADD_F32 dispatch failed at node %d\\n",\n                i);\n            ggml_cuda8_context_destroy(ctx);\n            return (enum ggml_status) -1;\n        }\n    }\n\n    ggml_cuda8_context_destroy(ctx);\n    std::printf("ggml-cuda8/backend: graph_compute SUCCESS\\n");\n    return GGML_STATUS_SUCCESS;\n}\n\nstatic void cuda8_backend_graph_optimize(ggml_backend_t backend, struct ggml_cgraph * cgraph) {\n    (void) backend;\n    (void) cgraph;\n    std::printf("ggml-cuda8/backend: graph_optimize stub PASS\\n");\n}\n\nstatic struct ggml_backend_i cuda8_backend_i;\nstatic bool cuda8_backend_i_initialized = false;\n\nstatic void cuda8_backend_iface_init(void) {\n    if (cuda8_backend_i_initialized) return;\n    std::memset(&cuda8_backend_i, 0, sizeof(cuda8_backend_i));\n\n    cuda8_backend_i.get_name = cuda8_backend_get_name;\n    cuda8_backend_i.free = cuda8_backend_free;\n\n    // Optional async/tensor callbacks remain NULL for now.\n    cuda8_backend_i.synchronize = cuda8_backend_synchronize;\n\n    // Real ggml_backend_i graph callback slots matching this checkout.\n    cuda8_backend_i.graph_plan_create = cuda8_backend_graph_plan_create;\n    cuda8_backend_i.graph_plan_free = cuda8_backend_graph_plan_free;\n    cuda8_backend_i.graph_plan_update = cuda8_backend_graph_plan_update;\n    cuda8_backend_i.graph_plan_compute = cuda8_backend_graph_plan_compute;\n    cuda8_backend_i.graph_compute = cuda8_backend_graph_compute;\n    cuda8_backend_i.graph_optimize = cuda8_backend_graph_optimize;\n\n    cuda8_backend_i_initialized = true;\n}\n\nextern "C" ggml_backend_t ggml_cuda8_ggml_backend_init(int device) {\n    cuda8_backend_iface_init();\n\n    ggml_cuda8_ggml_backend_context * ctx =\n        (ggml_cuda8_ggml_backend_context *) std::malloc(sizeof(ggml_cuda8_ggml_backend_context));\n    if (ctx == NULL) return NULL;\n    ctx->device = device;\n\n    ggml_backend_t backend = (ggml_backend_t) std::malloc(sizeof(struct ggml_backend));\n    if (backend == NULL) {\n        std::free(ctx);\n        return NULL;\n    }\n\n    std::memset(backend, 0, sizeof(*backend));\n    backend->iface = cuda8_backend_i;\n    backend->context = ctx;\n    return backend;\n}\n\nextern "C" int ggml_cuda8_ggml_backend_is_cuda8(ggml_backend_t backend) {\n    if (backend == NULL || backend->iface.get_name == NULL) return 0;\n    const char * name = backend->iface.get_name(backend);\n    return name != NULL && std::strcmp(name, "CUDA8") == 0;\n}\n\nextern "C" ggml_backend_buffer_type_t ggml_cuda8_ggml_backend_get_default_buffer_type(ggml_backend_t backend) {\n    if (!ggml_cuda8_ggml_backend_is_cuda8(backend)) return NULL;\n    return ggml_cuda8_ggml_buffer_type();\n}\n\nextern "C" int ggml_cuda8_ggml_backend_dispatch_op(\n    ggml_backend_t backend,\n    ggml_cuda8_context * ctx,\n    int op,\n    const ggml_tensor * src0,\n    const ggml_tensor * src1,\n    ggml_tensor * dst\n) {\n    if (!ggml_cuda8_ggml_backend_is_cuda8(backend)) {\n        std::fprintf(stderr, "ggml-cuda8/backend-dispatch: invalid backend\\n");\n        return -1;\n    }\n\n    if (ctx == NULL) {\n        std::fprintf(stderr, "ggml-cuda8/backend-dispatch: NULL CUDA8 context\\n");\n        return -1;\n    }\n\n    if (!ggml_cuda8_dispatch_supported(ctx, op, src0, src1, dst)) {\n        std::fprintf(stderr, "ggml-cuda8/backend-dispatch: unsupported op/layout op=%d\\n", op);\n        return -1;\n    }\n\n    return ggml_cuda8_dispatch_execute(ctx, op, src0, src1, dst);\n}\n'
PROBE_TEXT = '// ggml/src/ggml-cuda8/ggml-cuda8-ggml-backend-graph-compute-add-smoke.cpp\n//\n// G15A smoke: real backend->iface.graph_compute dispatch of one tiny ADD_F32 graph.\n//\n// This creates a normal ggml metadata graph with one ADD node, but tensor data\n// pointers are assigned into a backend-owned CUDA8 buffer. The CUDA8 backend\'s\n// graph_compute walks the cgraph and dispatches the ADD node through the existing\n// residency-aware CUDA8 dispatcher.\n\n#include "ggml-cuda8-ggml-backend.h"\n#include "ggml-cuda8-ggml-buffer.h"\n\n#include "ggml.h"\n#include "ggml-backend.h"\n#include "ggml-backend-impl.h"\n\n#include <cstdio>\n#include <cstdlib>\n#include <cstring>\n#include <stdint.h>\n#include <vector>\n#include <cmath>\n\nstatic bool expect_resident(const char * label, const ggml_tensor * t, size_t bytes, ggml_backend_buffer_t expected, size_t expected_offset) {\n    ggml_backend_buffer_t owner = NULL;\n    size_t offset = 0;\n    if (!ggml_cuda8_ggml_tensor_is_device_resident(t, bytes, &owner, &offset)) {\n        std::fprintf(stderr, "%s: residency not found\\n", label);\n        return false;\n    }\n    if (owner != expected || offset != expected_offset) {\n        std::fprintf(stderr, "%s: residency mismatch offset=%zu expected=%zu\\n", label, offset, expected_offset);\n        return false;\n    }\n    std::printf("%s residency PASS offset=%zu\\n", label, offset);\n    return true;\n}\n\nint main(int argc, char ** argv) {\n    (void) argc;\n    (void) argv;\n\n    std::printf("ggml-cuda8-ggml-backend-graph-compute-add-smoke: starting\\n");\n\n    ggml_backend_t backend = ggml_cuda8_ggml_backend_init(0);\n    if (backend == NULL) {\n        std::fprintf(stderr, "backend init failed\\n");\n        return 1;\n    }\n\n    if (!ggml_cuda8_ggml_backend_is_cuda8(backend)) {\n        std::fprintf(stderr, "backend identity check failed\\n");\n        backend->iface.free(backend);\n        return 1;\n    }\n\n    if (backend->iface.graph_compute == NULL) {\n        std::fprintf(stderr, "backend graph_compute callback is NULL\\n");\n        backend->iface.free(backend);\n        return 1;\n    }\n\n    std::printf("backend name: %s\\n", backend->iface.get_name(backend));\n\n    ggml_backend_buffer_type_t buft = ggml_cuda8_ggml_backend_get_default_buffer_type(backend);\n    if (buft == NULL) {\n        std::fprintf(stderr, "backend default buffer type is NULL\\n");\n        backend->iface.free(backend);\n        return 1;\n    }\n\n    std::printf("backend default buffer type: %s\\n", buft->iface.get_name(buft));\n\n    const int n = 512;\n    const size_t bytes = (size_t) n * sizeof(float);\n    const size_t off_a = 0;\n    const size_t off_b = 4096;\n    const size_t off_c = 8192;\n    const size_t total_size = 12288;\n\n    ggml_backend_buffer_t buffer = buft->iface.alloc_buffer(buft, total_size);\n    if (buffer == NULL) {\n        std::fprintf(stderr, "backend-owned buffer allocation failed\\n");\n        backend->iface.free(backend);\n        return 1;\n    }\n\n    void * base = buffer->iface.get_base(buffer);\n    if (base == NULL) {\n        std::fprintf(stderr, "buffer base is NULL\\n");\n        buffer->iface.free_buffer(buffer);\n        backend->iface.free(backend);\n        return 1;\n    }\n\n    std::printf("backend-owned graph buffer size: %zu\\n", buffer->size);\n    std::printf("buffer base:                     %p\\n", base);\n    std::printf("A offset:                        %zu\\n", off_a);\n    std::printf("B offset:                        %zu\\n", off_b);\n    std::printf("C offset:                        %zu\\n", off_c);\n\n    uint8_t * base_u8 = (uint8_t *) base;\n\n    const size_t meta_size = 16 * 1024;\n    std::vector<uint8_t> meta(meta_size, 0);\n    struct ggml_init_params params;\n    params.mem_size = meta_size;\n    params.mem_buffer = &meta[0];\n    params.no_alloc = true;\n\n    struct ggml_context * gctx = ggml_init(params);\n    if (gctx == NULL) {\n        std::fprintf(stderr, "ggml_init failed\\n");\n        buffer->iface.free_buffer(buffer);\n        backend->iface.free(backend);\n        return 1;\n    }\n\n    struct ggml_tensor * a = ggml_new_tensor_1d(gctx, GGML_TYPE_F32, n);\n    struct ggml_tensor * b = ggml_new_tensor_1d(gctx, GGML_TYPE_F32, n);\n    struct ggml_tensor * c = ggml_add(gctx, a, b);\n\n    a->data = base_u8 + off_a;\n    b->data = base_u8 + off_b;\n    c->data = base_u8 + off_c;\n\n    if (buffer->iface.init_tensor(buffer, a) != GGML_STATUS_SUCCESS ||\n        buffer->iface.init_tensor(buffer, b) != GGML_STATUS_SUCCESS ||\n        buffer->iface.init_tensor(buffer, c) != GGML_STATUS_SUCCESS) {\n        std::fprintf(stderr, "init_tensor failed\\n");\n        ggml_free(gctx);\n        buffer->iface.free_buffer(buffer);\n        backend->iface.free(backend);\n        return 1;\n    }\n\n    if (!expect_resident("A", a, bytes, buffer, off_a) ||\n        !expect_resident("B", b, bytes, buffer, off_b) ||\n        !expect_resident("C", c, bytes, buffer, off_c)) {\n        ggml_free(gctx);\n        buffer->iface.free_buffer(buffer);\n        backend->iface.free(backend);\n        return 1;\n    }\n\n    std::vector<float> a_host(n);\n    std::vector<float> b_host(n);\n    std::vector<float> c_ref(n);\n    std::vector<float> c_out(n, 0.0f);\n\n    for (int i = 0; i < n; ++i) {\n        a_host[i] = ((float) ((i * 17 + 3) % 101) - 50.0f) * 0.03125f;\n        b_host[i] = ((float) ((i * 19 + 5) % 97) - 48.0f) * 0.015625f;\n        c_ref[i] = a_host[i] + b_host[i];\n    }\n\n    buffer->iface.clear(buffer, 0);\n    buffer->iface.set_tensor(buffer, a, &a_host[0], 0, bytes);\n    buffer->iface.set_tensor(buffer, b, &b_host[0], 0, bytes);\n\n    struct ggml_cgraph * graph = ggml_new_graph(gctx);\n    ggml_build_forward_expand(graph, c);\n\n    std::printf("synthetic graph n_nodes=%d\\n", graph->n_nodes);\n    for (int i = 0; i < graph->n_nodes; ++i) {\n        std::printf("graph node %d op=%d\\n", i, (int) graph->nodes[i]->op);\n    }\n\n    enum ggml_status status = backend->iface.graph_compute(backend, graph);\n    if (status != GGML_STATUS_SUCCESS) {\n        std::fprintf(stderr, "backend graph_compute returned %d\\n", (int) status);\n        ggml_free(gctx);\n        buffer->iface.free_buffer(buffer);\n        backend->iface.free(backend);\n        return 1;\n    }\n\n    buffer->iface.get_tensor(buffer, c, &c_out[0], 0, bytes);\n\n    double max_abs_err = 0.0;\n    for (int i = 0; i < n; ++i) {\n        const double diff = (double) c_out[i] - (double) c_ref[i];\n        const double abs_err = diff < 0.0 ? -diff : diff;\n        if (abs_err > max_abs_err) max_abs_err = abs_err;\n    }\n\n    std::printf("graph_compute ADD_F32 max_abs_err=%.9g\\n", max_abs_err);\n    if (max_abs_err > 1e-6) {\n        std::fprintf(stderr, "graph_compute ADD_F32 verification FAIL\\n");\n        ggml_free(gctx);\n        buffer->iface.free_buffer(buffer);\n        backend->iface.free(backend);\n        return 1;\n    }\n\n    std::printf("graph_compute ADD_F32 verification PASS\\n");\n\n    ggml_free(gctx);\n    buffer->iface.free_buffer(buffer);\n    backend->iface.free(backend);\n\n    std::printf("ggml-cuda8-ggml-backend-graph-compute-add-smoke: SUCCESS\\n");\n    return 0;\n}\n'
CMAKE_TARGET = '\n# ---------------------------------------------------------------------------\n# G15A real backend->iface.graph_compute ADD_F32 smoke:\n#   - builds one tiny synthetic ggml ADD graph\n#   - tensor data points into backend-owned CUDA8 buffer\n#   - backend graph_compute dispatches ADD through residency-aware dispatcher\n# ---------------------------------------------------------------------------\n\ncuda_add_executable(ggml-cuda8-ggml-backend-graph-compute-add-smoke\n    ggml-cuda8-ggml-backend-graph-compute-add-smoke.cpp\n)\n\ntarget_link_libraries(ggml-cuda8-ggml-backend-graph-compute-add-smoke\n    ggml-cuda8-kernels\n    ${CUDA_LIBRARIES}\n)\n'

def backup(path):
    if os.path.exists(path):
        b = path + ".g15a-backup-" + str(int(time.time()))
        with open(path, "r") as f:
            data = f.read()
        with open(b, "w") as f:
            f.write(data)
        print("backup", b)

def write(path, text):
    backup(path)
    with open(path, "w") as f:
        f.write(text)
    print("wrote", path)

write(BACKEND_H, BACKEND_H_TEXT)
write(BACKEND_CPP, BACKEND_CPP_TEXT)
write(PROBE_CPP, PROBE_TEXT)
backup(CMAKE)
with open(CMAKE, "r") as f:
    cm = f.read()
if "ggml-cuda8-ggml-backend-graph-compute-add-smoke" not in cm:
    if not cm.endswith("\n"):
        cm += "\n"
    cm += CMAKE_TARGET
    with open(CMAKE, "w") as f:
        f.write(cm)
    print("patched", CMAKE)
else:
    print("CMake target already present")
print("")
print("G15A writer complete.")
